  `delete_time` datetime(6) NULL DEFAULT NULL COMMENT '删除时间',
  `storage_mode` smallint NOT NULL DEFAULT 1 COMMENT '存储模式 (1 本地 2 阿里云 3 七牛云 4 腾讯云)',
