-- ----------------------------
-- Table structure for nest_tool_crontab_log
-- ----------------------------
DROP TABLE IF EXISTS `nest_tool_crontab_log`;
CREATE TABLE `nest_tool_crontab_log`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `crontab_id` int UNSIGNED NULL DEFAULT NULL COMMENT '任务ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '任务名称',
  `target` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '任务调用目标',
  `status` smallint NOT NULL DEFAULT 0 COMMENT '执行状态(0执行中 1成功 2失败 3跳过)',
  `create_time` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `update_time` datetime(6) NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '修改时间',
  `delete_time` datetime(6) NULL DEFAULT NULL COMMENT '删除时间',
  `result_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '执行结果信息',
  `trigger_type` smallint NOT NULL DEFAULT 1 COMMENT '触发方式(1定时 2手动)',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始执行时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束执行时间',
  `duration_ms` int NULL DEFAULT NULL COMMENT '执行耗时(毫秒)',
  `parameter` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '任务调用参数',
  `exception_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '异常信息',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = Dynamic;

